interface Service { fetch(): Promise<string> }

class RealService implements Service {
  async fetch() { return 'data' }
}

class ServiceProxy implements Service {
  private real?: RealService
  async fetch() {
    if (!this.real) this.real = new RealService()
    return this.real.fetch()
  }
}

interface Repo { get(id:string): Promise<any> }

class AuthzProxy implements Repo {
  constructor(private repo: Repo, private user: User) {}
  async get(id:string) {
    if (!this.user.hasRole('reader')) throw new Error('Forbidden')
    return this.repo.get(id)
  }
}

// Version A: wrapper preserves interface and delegates
class PaymentProxy implements Payment {
  constructor(private real: Payment, private user: User) {}
  process(amount:number) {
    if (!this.user.can('pay')) throw new Error('Forbidden')
    return this.real.process(amount)
  }
}

// Version B: core service accepts user directly and performs checks
class RealPayment implements Payment {
  constructor(private user: User) {}
  process(amount:number) {
    if (!this.user.can('pay')) throw new Error('Forbidden')
    // perform payment
  }
}
